/* @lc app=leetcode id=2812 lang=kotlin */ class Solution { fun mk(s: Array<BooleanArray>, r: Int, c: Int) { s[r][c] = true } fun maximumSafenessFactor(grid: List<List<Int>>): Int = grid.size.let { n -> Array(n) { IntArray(n) { -1 } }.also { d -> generateSequence(grid.indices.flatMap { i -> grid.indices.filter { grid[i][it] == 1 }.map { i to it } }.onEach { (i, j) -> d[i][j] = 0 } to 0) { (f, lv) -> f.flatMap { (i, j) -> listOf(i + 1 to j, i - 1 to j, i to j + 1, i to j - 1) }.filter { (i, j) -> i in 0 until n && j in 0 until n && d[i][j] == -1 }.distinct().onEach { (i, j) -> d[i][j] = lv + 1 }.takeIf { it.isNotEmpty() }?.let { it to lv + 1 } }.count() }.let { d -> Array(n) { BooleanArray(n) }.let { seen -> java.util.PriorityQueue<IntArray>(compareByDescending<IntArray> { it[0] }).also { it.add(intArrayOf(d[0][0], 0, 0)) }.let { pq -> generateSequence { pq.poll() }.filter { !seen[it[1]][it[2]] }.onEach { c -> mk(seen, c[1], c[2]).also { listOf(c[1] + 1 to c[2], c[1] - 1 to c[2], c[1] to c[2] + 1, c[1] to c[2] - 1).filter { (r, cc) -> r in 0 until n && cc in 0 until n && !seen[r][cc] }.forEach { (r, cc) -> pq.add(intArrayOf(minOf(c[0], d[r][cc]), r, cc)) } } }.first { it[1] == n - 1 && it[2] == n - 1 }[0] } } } } }